            else:
                warn(depot, 'bad field count', len(fields), len(header), fields[:4]); continue
        r = dict(zip(header, fields))
        recs.append((r, rowunit, dict(dirs)))
    out = []
    for r, rowunit, d in recs:
        dform = d.get('dates') or d.get('date format') or cfg['base_date']
        wunit_dir = None
        dm = cfg['dmark']
        if depot in ('east',):
