        elif depot in ('river', 'west'):
            wunit_dir = d.get('weight unit')
        if wunit_dir:
            if 'decimal comma' in wunit_dir:
                dm = ','
            wunit_dir = unit_in(wunit_dir)
        if depot == 'east':
            typ = {'N': 'new', 'C': 'corr', 'V': 'void'}[r['type'].strip().upper()]
            id_ = norm_id(r['id']); ship = r['shipped']; w = r['gross']; st = r['status']
        elif depot == 'lakeside':
