            id_ = norm_id(r['id']); ship = r['shipped']; w = r['gross_kg']; st = r['status']
        elif depot == 'harbor':
            typ = {'NEW': 'new', 'COR': 'corr', 'VOID': 'void'}[r['rec'].strip().upper()]
            id_ = norm_id(r['ref']); ship = r['date']; w = r['weight']; st = {'DLV': 'delivered', 'DLL': 'delivered_late'}.get(r['state'].strip().upper(), r['state'])
        elif depot == 'river':
            typ = {'': 'new', 'C': 'corr', 'V': 'void'}[r['t'].strip().upper()]
            id_ = norm_id(r['ref']); ship = r['shipped']; w = r['weight']; st = r['status']
        else:
            typ = {'N': 'new', 'C': 'corr', 'V': 'void'}[r['typ'].strip().upper()]
            id_ = norm_id(r['id']); ship = r['shipped']; w = r['weight']; st = r['status']
        if typ == 'void':
            out.append(mk('void', id_, None, None, None)); continue
        # unit
        unit = None
        wtxt = w.strip()
        m = re.match(r'^(.*?)\s*(kg|g|lb|oz)$', wtxt, re.I)
        if m:
            wtxt = m[1]; unit = m[2].lower()
        if depot == 'lakeside':
            unit = unit or 'kg'
        unit = unit or rowunit or wunit_dir or cfg['base_unit']
        kg = parse_num(wtxt, dm) * FACT[unit]
        month = month_of(ship, dform)
        out.append(mk(typ, id_, month, kg, st))
    return seq, out


FW = {
    'FW1': dict(len=42, id=(1, 9), type=(10, 10), shipped=(11, 17), weight=(18, 25), status=(26, 26), dfmt='yd', wu='g', wdiv=1),
    'FW2': dict(len=43, id=(2, 10), type=(1, 1), shipped=(11, 18), weight=(19, 26), status=(27, 27), dfmt='ymd', wu='kg', wdiv=100),
    'FW3': dict(len=41, id=(1, 9), type=(17, 17), shipped=(10, 16), weight=(18, 24), status=(25, 25), dfmt='yd', wu='lb', wdiv=10),
}
SCODE = {'D': 'delivered', 'L': 'delivered_late'}


def fixed(text):
    seq = None
    layout = None
    out = []
    for line in text.split('\n'):
        if line.endswith('\r'):
            line = line[:-1]
        if line.startswith('\x0c') or 'SHIPMENT LISTING' in line and 'PAGE' in line:
            continue
        if line.strip() == '':
            continue
        if line.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\w+)', line)
            if m:
                layout = m[1]
            m = re.match(r'#SEQ\s+(\d+)', line)
            if m:
                seq = int(m[1])
            continue
        L = len(line)
        lay = layout
        for name, spec in FW.items():
            if spec['len'] == L:
                lay = name
                break
        else:
            # trailing-space trimmed? try layout in force with padding
            lay = layout
            if lay is None:
                warn('south bad line', repr(line)); continue
            line = line.ljust(FW[lay]['len'])
        sp = FW[lay]
        def f(k):
            a, b = sp[k]
            return line[a - 1:b]
        typ = {'N': 'new', 'C': 'corr', 'V': 'void'}[f('type')]
        id_ = norm_id(f('id'))
        if typ == 'void':
            out.append(mk('void', id_, None, None, None)); continue
        sh = f('shipped')
        if sp['dfmt'] == 'yd':
            d = date(int(sh[:4]), 1, 1) + timedelta(days=int(sh[4:7]) - 1)
        else:
            d = date(int(sh[:4]), int(sh[4:6]), int(sh[6:8]))
        kg = Decimal(int(f('weight'))) / sp['wdiv'] * FACT[sp['wu']]
        out.append(mk(typ, id_, '%04d-%02d' % (d.year, d.month), kg, SCODE.get(f('status'), f('status'))))
    return seq, out


def jsonl(text):
    seq = None
    out = []
    def handle(o):
        nonlocal seq
        if 'meta' in o and isinstance(o['meta'], dict) and 'id' not in o:
            if 'seq' in o['meta']:
                seq = int(o['meta']['seq'])
            return
        kind = (o.get('kind') or 'new').lower()
        typ = {'new': 'new', 'amend': 'corr', 'void': 'void'}[kind]
        id_ = norm_id(o['id'])
        if typ == 'void':
            out.append(mk('void', id_, None, None, None)); return
        kg = None
        for k, v in o.items():
            m = re.match(r'^weight_(kg|g|lb|oz)$', k)
            if m:
                kg = Decimal(str(v)) * FACT[m[1]]
        out.append(mk(typ, id_, month_of(o['shipped_at']), kg, o['status']))
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        o = json.loads(line)
        for x in (o if isinstance(o, list) else [o]):
            handle(x)
    return seq, out


def xml(text):
    text = re.sub(r'^\s*<\?xml[^>]*\?>', '', text)
    root = ET.fromstring(text)
    seq = int(root.get('seq'))
    runit = (root.get('weight-unit') or 'kg').lower()
    out = []
    for e in root.iter('shipment'):
        t = (e.get('type') or 'new').lower()
        typ = {'new': 'new', 'correction': 'corr', 'void': 'void'}[t]
        id_ = norm_id(e.get('id'))
        if typ == 'void':
            out.append(mk('void', id_, None, None, None)); continue
        we = e.find('weight')
        unit = (we.get('unit') or runit).lower()
        kg = Decimal(we.text.strip()) * FACT[unit]
        sh = e.get('shipped')
        if sh is None:
            c = e.find('shipped')
            sh = c.text.strip()
        st = e.find('status').text
        out.append(mk(typ, id_, month_of(sh), kg, st))
    return seq, out


def read_export(path, depot):
    text = decode(open(path, 'rb').read())
    if depot == 'central':
        return xml(text)
    if depot == 'south':
        return fixed(text)
    if depot == 'north':
        return jsonl(text)
    return delimited(text, depot)


def main():
    data, outf = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data)):
        p = os.path.join(data, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        exports.setdefault(depot, [])
        seq, recs = read_export(p, depot)
        exports[depot].append((seq if seq is not None else -1, name, recs))
    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        lst.sort(key=lambda x: (x[0], x[1]))
        for seq, name, recs in lst:
            for r in recs:
                i = r['id']
                if r['type'] == 'new':
                    if i in cur:
                        resends += 1
                    else:
                        cur[i] = r
                elif r['type'] == 'corr':
                    cur[i] = r
                    corrections += 1
                else:
                    cur.pop(i, None)
                    corrections += 1
        current[depot] = cur
    owners = {}
    for depot, cur in current.items():
        for i in cur:
            owners.setdefault(i, []).append(depot)
    rank = lambda d: ORDER.index(d) if d in ORDER else len(ORDER)
    handovers = sum(1 for v in owners.values() if len(v) > 1)
    dep = {d: [0, Decimal(0)] for d in exports}
    mon = {}
    for i, ds in owners.items():
        d = min(ds, key=rank)
        r = current[d][i]
        if not counted(r['status']):
            continue
        dep[d][0] += 1
        dep[d][1] += r['kg']
        m = mon.setdefault(r['month'], [0, Decimal(0)])
        m[0] += 1
        m[1] += r['kg']
    q = lambda x: float(round(x, 2))
    res = {
        'depots': {d: {'shipments': v[0], 'total_kg': q(v[1])} for d, v in sorted(dep.items())},
        'months': {m: {'shipments': v[0], 'total_kg': q(v[1])} for m, v in sorted(mon.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(outf, 'w') as f:
        json.dump(res, f, indent=2)
    for w in WARN[:20]:
        print('WARN', w, file=sys.stderr)


main()
